sponsiveness."}, {"id": "b911dd0a-b885-4f28-8558-454de5b5464a", "type": "subtopic", "title": "Global production networks", "children": [{"id": "bce7ca4f-8eab-48ea-b5fe-16347b56438c", "type": "concept", "title": "Focused factories"}, {"id": "eefe1a03-e902-4e55-94f1-555b038cfff4", "type": "concept", "title": "Postponement"}, {"id": "f98c430a-c848-4012-99b5-0d5fa027f19b", "type": "concept", "title": "Dual sourcing"}, {"id": "457ceedb-1b48-4b35-93fd-e63475d8b71b", "type": "concept", "title": "Regional hubs"}], "description": "Gist: Firms decide what to make where based on cost, risk, skill, demand, and policy."}, {"id": "c9eccca3-00d7-4de3-a7de-eec64a726239", "type": "subtopic", "title": "Make-buy and outsourcing", "children": [{"id": "a114d3a6-5450-49d8-aba3-95a4700f312a", "type": "concept", "title": "Core capability"}, {"id": "8b46ee1d-9a6e-45e9-acbf-2e36fdd2b9db", "type": "concept", "title": "Supplier capability"}, {"id": "0be086a5-88b5-4dfd-9e07-8c583e020ed9", "type": "concept", "title": "Transaction costs"}, {"id": "1001c77f-83d0-445f-b2f1-91fe3b329207", "type": "concept", "title": "Quality risk"}], "description": "Gist: Students examine what should remain internal and what should be outsourced."}]}, {"id": "1cd2a95c-777f-4436-ae9d-a024d957c08c", "type": "topic", "title": "Logistics, Transportation, and Distribution Systems", "description": "Study the movement of goods through modes, nodes, carriers, warehouses, ports, and last-mile systems.", "children": [{"id": "c41eadf4-ea25-4899-9a6f-cec024752b2e", "type": "subtopic", "title": "Transportation modes", "children": [{"id": "94451221-f91f-4f9a-a0e2-712534d07a3b", "type": "concept", "title": "Ocean"}, {"id": "ce2a6059-07b5-4940-a000-e84ae910bd43", "type": "concept", "title": "Air"}, {"id": "91cc2999-a083-4460-abba-e110c1bae283", "type": "concept", "title": "Rail"}, {"id": "fd4ff0df-54b9-4328-a14e-90ef1d2844cf", "type": "concept", "title": "Truck and intermodal"}], "description": "Gist: Mode choice shapes cost, speed, reliability, emissions, and customer service."}, {"id": "8212b811-84a6-4bde-9d8e-f8e7b6cf56d6", "type": "subtopic", "title": "Distribution design", "children": [{"id": "341a3662-e799-46f1-9d2c-87866dd32feb", "type": "concept", "title": "Direct shipping"}, {"id": "da577d12-0268-4783-a8b8-273ad9c32b7c", "type": "concept", "title": "Hub-and-spoke"}, {"id": "77f889cd-d4ce-41ac-aaaa-12579a2054b3", "type": "concept", "title": "Cross-docking"}, {"id": "66739f10-6830-4192-9891-cf369e73d3e6", "type": "concept", "title": "Milk runs"}], "description": "Gist: Distribution choices connect network structure to customer promises and inventory policy."}, {"id": "de181e01-6ceb-42ba-aa49-8a7aab1cac8f", "type": "subtopic", "title": "Global logistics execution", "children": [{"id": "bef38c10-106f-48ae-9b19-610820379f30", "type": "concept", "title": "Freight forwarders"}, {"id": "67a24c19-a086-4243-8dff-3c850337ec82", "type": "concept", "title": "3PLs"}, {"id": "76a841bd-ca40-4e36-b319-9f4df036765e", "type": "concept", "title": "Port congestion"}, {"id": "ffb31f47-ddba-40d5-88de-06dce6a9380a", "type": "concept", "title": "Demurrage and detention"}], "description": "Gist: Students learn the practical complexity of freight, ports, carriers, and exceptions."}]}, {"id": "c995ead3-be56-417e-90d6-9c6013db91b8", "type": "topic", "title": "Warehousing, Fulfillment, and Omnichannel Operations", "description": "Analyze how warehouse design, fulfillment logic, automation, and customer promises shape cost and service.", "children": [{"id": "dba4c7a2-f948-4431-984d-e34b70570f50", "type": "subtopic", "title": "Warehouse roles", "children": [{"id": "5392063c-bad7-414b-bc49-14d10ff4f08b", "type": "concept", "title": "Receiving"}, {"id": "84fd3595-365f-4fe9-9686-7f4ab070208a", "type": "concept", "title": "Putaway"}, {"id": "7c703f36-b565-4ea9-ac70-f544dd2b26c7", "type": "concept", "title": "Picking"}, {"id": "19e25a27-f1e0-461a-87f2-3179111d0d56", "type": "concept", "title": "Packing and shipping"}], "description": "Gist: Warehouses support storage, consolidation, postponement, returns, and customer response."}, {"id": "1015bb0e-0856-4776-8bdf-16de736c83fd", "type": "subtopic", "title": "Fulfillment strategy", "children": [{"id": "48549713-2b54-4f52-9945-d8110b573e4f", "type": "concept", "title": "Ship-from-store"}, {"id": "0202c177-4665-4c4b-a67c-96cd76febcaa", "type": "concept", "title": "Micro-fulfillment"}, {"id": "16542e6a-8ed3-414b-aca1-769f101ce804", "type": "concept", "title": "Click and collect"}, {"id": "878a52d0-8d53-4f0f-84d1-7501bd7a89d4", "type": "concept", "title": "Last mile"}], "description": "Gist: E-commerce and omnichannel promises require different fulfillment designs."}, {"id": "e900069b-57a0-4c9b-b6a7-b31bb97405b6", "type": "subtopic", "title": "Automation and labor", "children": [{"id": "22cd9d61-baf2-49ad-af4f-916702e781a1", "type": "concept", "title": "WMS"}, {"id": "daf01210-c92d-47ed-9bbb-d808337181ee", "type": "concept", "title": "Robotics"}, {"id": "45126c3b-b8e3-437b-88ac-244cdf389278", "type": "concept", "title": "Slotting"}, {"id": "f6167436-3726-4ba2-a3cb-624a0b8081da", "type": "concept", "title": "Labor standards"}], "description": "Gist: Students evaluate automation through productivity, flexibility, safety, and workforce implications."}]}, {"id": "d81dfab9-6dbb-4b93-91f4-7358a6c406b2", "type": "topic", "title": "Supply Chain Information Systems, ERP, and Data Standards", "description": "Understand the systems and data flows that make end-to-end planning, execution, and visibility possible.", "children": [{"id": "ad6271e4-2c0f-4c84-b384-d5c4b27380c0", "type": "subtopic", "title": "System landscape", "children": [{"id": "41a75c34-4a24-4ae7-a781-a1d5c4ae377f", "type": "concept", "title": "ERP"}, {"id": "c8b53876-fa29-4033-b7de-6025f9fa8edf", "type": "concept", "title": "WMS"}, {"id": "25738a10-adeb-4372-a361-e1f2f0758a91", "type": "concept", "title": "TMS"}, {"id": "a50389aa-d6ea-48f9-a15b-e892225cf81b", "type": "concept", "title": "APS"}], "description": "Gist: Modern supply chains run on connected planning, execution, and financial systems."}, {"id": "30ae8230-c8f6-4bef-b36f-a598a9fe0783", "type": "subtopic", "title": "Data quality", "children": [{"id": "cf43c88c-a8ee-44ee-b65c-74e497aa3f48", "type": "concept", "title": "SKU master"}, {"id": "ad18c5e6-33f7-4ae1-b187-9046d564e96e", "type": "concept", "title": "Supplier master"}, {"id": "855d3062-6845-4720-be46-d8ab17227ccb", "type": "concept", "title": "Location data"}, {"id": "02148eed-2154-41f8-a69d-73605fab3cd1", "type": "concept", "title": "Data governance"}], "description": "Gist: Visibility depends on clean master data and consistent definitions."}, {"id": "fc593eb8-4852-4094-883d-275055b0c658", "type": "subtopic", "title": "Integration", "children": [{"id": "651303f6-6f9f-4f4e-a0be-20107bab84a8", "type": "concept", "title": "EDI"}, {"id": "9d38916b-34aa-4466-9e62-9ace9703e365", "type": "concept", "title": "APIs"}, {"id": "0b8a0aa4-d152-4e79-af3f-82e1dd17be09", "type": "concept", "title": "Control points"}, {"id": "f1120064-e94f-42fc-95e2-60a2d7eb66e9", "type": "concept", "title": "Exception workflows"}], "description": "Gist: Students learn why handoffs between systems create risk and latency."}]}, {"id": "50ccbcf9-de11-4835-9579-ae8ae0052cd2", "type": "topic", "title": "Digital Supply Chains, Analytics, AI, and Control Towers", "description": "Use analytics, optimization, simulation, visibility platforms, and AI to support better supply-chain decisions.", "children": [{"id": "537ddf7f-e4de-494a-aba4-ae661fe8eed4", "type": "subtopic", "title": "Analytics uses", "children": [{"id": "43242176-bb32-440d-8814-8fe12880691a", "type": "concept", "title": "Descriptive analytics"}, {"id": "d8112fa4-b474-4a18-8404-872f9191c1a5", "type": "concept", "title": "Predictive analytics"}, {"id": "31b595e5-785e-4ad1-845b-8fe700e75f17", "type": "concept", "title": "Prescriptive analytics"}, {"id": "25746f2f-f59e-465d-b71f-d39ca352fe51", "type": "concept", "title": "Optimization"}], "description": "Gist: Analytics supports forecasting, inventory, routing, network design, risk sensing, and performance management."}, {"id": "02edb493-0eb8-469c-b148-4735953d54d1", "type": "subtopic", "title": "Control towers", "children": [{"id": "0d43f742-8794-404f-adfc-9b90939b74fe", "type": "concept", "title": "End-to-end visibility"}, {"id": "1d582c76-fa9c-4de9-8496-eb280c958692", "type": "concept", "title": "Alerting"}, {"id": "bf9b7029-95a3-4e18-adcf-250e215af1dd", "type": "concept", "title": "Root cause analysis"}, {"id": "5334b8d2-a4a7-4647-8d29-df702038bcd8", "type": "concept", "title": "Scenario response"}], "description": "Gist: Control towers give decision-makers visibility and exception management across networks."}, {"id": "2228d2d4-4218-47c8-8af2-01655da32c5b", "type": "subtopic", "title": "AI and automation", "children": [{"id": "210933ec-24fc-4583-acff-e5e6dfb5fb97", "type": "concept", "title": "Demand sensing"}, {"id": "daa6ddd8-2b3e-4755-be90-9bd1ddf5c01c", "type": "concept", "title": "ETA prediction"}, {"id": "c2d284ce-300b-46a0-bc47-cb83321df748", "type": "concept", "title": "Supplier risk analytics"}, {"id": "111d0b8d-4dbc-407e-871b-85b2e85bbc18", "type": "concept", "title": "Human-in-the-loop"}], "description": "Gist: AI can improve speed and pattern recognition but requires governance and human judgment."}]}, {"id": "7d29a2ff-d021-4d6d-b586-9ccbd5b194e6", "type": "topic", "title": "Risk Mapping, Resilience, and Disruption Response", "description": "Prepare students to identify vulnerabilities, quantify exposure, design resilience, and respond to disruption.", "children": [{"id": "c0934862-e282-4916-a09e-705a6825d695", "type": "subtopic", "title": "Risk identification", "children": [{"id": "79435b44-fa29-46e6-a23b-5cd7e72dbae6", "type": "concept", "title": "Single-source risk"}, {"id": "3f6b1920-a14a-4786-abc6-48eaba568b4a", "type": "concept", "title": "Tier-n visibility"}, {"id": "68541a69-bfbb-43bb-aead-225a