{"id": "e94598d3-a6b2-4cf1-91d8-a97e644caea3", "type": "concept", "title": "Activity-based costing"}, {"id": "b2ac2e77-a4b8-43d0-8234-b4efb579b605", "type": "concept", "title": "Landed cost"}, {"id": "1e4da0f2-ad25-4411-b5fb-464987e510d5", "type": "concept", "title": "Logistics cost"}, {"id": "0c39133f-f153-4331-aa4e-2847c65d6f34", "type": "concept", "title": "Complexity cost"}], "description": "Gist: Students learn how customer, channel, product, and geography choices create different service costs."}, {"id": "48d90a61-be4b-40bb-bdcb-e1ab4a319039", "type": "subtopic", "title": "Performance metrics", "children": [{"id": "d37f1ae5-cc58-4c1e-b879-de4ac706d68e", "type": "concept", "title": "OTIF"}, {"id": "e271ddca-7c50-45ae-8401-b5fe90645d4c", "type": "concept", "title": "Perfect order"}, {"id": "95ce87da-241c-485b-b7cd-ffdf657b111c", "type": "concept", "title": "Inventory turns"}, {"id": "54ee70c2-f292-44c2-9226-d26702c16130", "type": "concept", "title": "Forecast accuracy"}], "description": "Gist: A balanced scorecard tracks cost, service, quality, resilience, cash, and sustainability."}, {"id": "c8da52db-dacb-4687-8f6e-e748500a1bc7", "type": "subtopic", "title": "Financial impact", "children": [{"id": "5044099f-53e3-4a8f-9fed-8243e09b63be", "type": "concept", "title": "Working capital"}, {"id": "0a4de43f-5da9-450c-b2dc-9fa549eab9e0", "type": "concept", "title": "COGS"}, {"id": "ba045f5c-a22f-499c-84bd-00de56c0e0bc", "type": "concept", "title": "Service revenue"}, {"id": "20bf791b-40f5-4242-9299-4bbd1a26e7ed", "type": "concept", "title": "Risk-adjusted cost"}], "description": "Gist: Supply-chain decisions affect revenue growth, margin, cash flow, and enterprise value."}]}, {"id": "e91df4ba-a884-4e5b-bc0f-52aa04484525", "type": "topic", "title": "Ethics, Labor, Compliance, and Responsible Global Sourcing", "description": "Examine responsible sourcing, labor standards, human rights, anti-corruption, and supplier accountability.", "children": [{"id": "a23e07b2-88fd-4c07-8c11-3b66780d29be", "type": "subtopic", "title": "Labor and human rights", "children": [{"id": "74aac471-5bf4-480a-b23c-45bcf199fb1b", "type": "concept", "title": "Supplier codes"}, {"id": "9170fdfd-9297-490b-bbbe-ab38bb2e0c87", "type": "concept", "title": "Audits"}, {"id": "541d5f50-0341-461c-8092-cc204ae3b848", "type": "concept", "title": "Corrective action"}, {"id": "ef4b415a-96da-4e32-901a-83e23930c63d", "type": "concept", "title": "Worker grievance systems"}], "description": "Gist: Global sourcing requires attention to wages, safety, forced labor, child labor, and worker voice."}, {"id": "320f1354-d6d3-4e69-8b2a-1305d2ee96ec", "type": "subtopic", "title": "Compliance and anti-corruption", "children": [{"id": "62216f5e-c060-4803-92c4-47fcb54d6f22", "type": "concept", "title": "FCPA awareness"}, {"id": "561c0c27-4aa0-436f-9fa5-d6635e8e9a5a", "type": "concept", "title": "Trade compliance"}, {"id": "ff3487a7-2189-45e2-9b33-c4048cc664c3", "type": "concept", "title": "Conflict minerals"}, {"id": "cfa2baa6-3540-4461-b8d1-ac51a7d3804a", "type": "concept", "title": "Restricted parties"}], "description": "Gist: Supply-chain teams manage legal, customs, anti-bribery, sanctions, and documentation risks."}, {"id": "713f0fba-124e-47b6-8ec0-be79c36c17a8", "type": "subtopic", "title": "Responsible governance", "children": [{"id": "80fb2c81-9c5c-49f4-96d3-0020790a38e8", "type": "concept", "title": "Supplier scorecards"}, {"id": "b8f28400-c9a0-4a38-ac2c-b30ed17f1e47", "type": "concept", "title": "Responsible procurement"}, {"id": "ea0a07c8-2dc8-4db6-a650-123334eca427", "type": "concept", "title": "Transparency"}, {"id": "d8035016-c227-4766-9e11-1d2156e86ed0", "type": "concept", "title": "Accountability"}], "description": "Gist: Students evaluate how firms turn values into enforceable supplier and sourcing practices."}]}, {"id": "facd2a53-2a7e-4551-b8ca-97671150a86c", "type": "topic", "title": "Global Supply Chain Strategy Capstone", "description": "Synthesize network design, sourcing, logistics, analytics, risk, sustainability, and performance metrics in a final strategic recommendation.", "children": [{"id": "8fd79fef-1427-4176-aa85-f4274332b0ff", "type": "subtopic", "title": "Problem framing", "children": [{"id": "f690fc4f-6acc-4cde-9a5a-0c259adbaac4", "type": "concept", "title": "Business context"}, {"id": "c069ac60-959c-4287-bdc1-37a3ce248963", "type": "concept", "title": "Network issue"}, {"id": "7b020c9c-7d75-4b34-807b-3863bf06a4a3", "type": "concept", "title": "Risk issue"}, {"id": "6ae40d3e-4b7e-45eb-8196-463032826da7", "type": "concept", "title": "Performance target"}], "description": "Gist: Students define a real supply-chain strategy problem with objectives, constraints, and stakeholder needs."}, {"id": "769127f8-450c-47d6-a883-24c8387f037b", "type": "subtopic", "title": "Integrated analysis", "children": [{"id": "840fa462-66c4-4dd9-af26-780244412c54", "type": "concept", "title": "Network map"}, {"id": "69cc9991-100f-4e51-96e5-756c30f34450", "type": "concept", "title": "Cost-service tradeoff"}, {"id": "80554d77-9fa3-43e0-b505-3e1e3b3f5bda", "type": "concept", "title": "Risk map"}, {"id": "2197a8e1-15be-4e46-a653-2522d00f54e0", "type": "concept", "title": "Sustainability lens"}], "description": "Gist: The capstone combines qualitative context with quantitative supply-chain reasoning."}, {"id": "ab52f008-bd37-4400-bb06-d5bac4688f32", "type": "subtopic", "title": "Recommendation and roadmap", "children": [{"id": "c53ac441-a976-40a0-a8a8-59c9c4f46a4e", "type": "concept", "title": "Strategic options"}, {"id": "b7c89724-b87d-400a-93b6-f6e013ecefcd", "type": "concept", "title": "Implementation roadmap"}, {"id": "01443740-8aa1-4859-8cb1-cb067b3896a4", "type": "concept", "title": "KPIs"}, {"id": "18b827e0-f48a-4da9-9711-ddf339dc02c2", "type": "concept", "title": "Executive presentation"}], "description": "Gist: Students produce an actionable plan with metrics, governance, milestones, and implementation risks."}]}], "dbBacked": true}$gs