update public.learning_paths
set
  title = 'Global Supply Chain Management',
  goal = 'Global Supply Chain Management',
  summary = 'Frame global supply chains as networks that connect strategy, demand, sourcing, production, logistics, service, finance, risk, technology, and sustainability. Topics study network design, trade and geopolitics, demand planning, inventory, procurement, manufacturing, logistics, fulfillment, information systems, analytics, risk, sustainability, performance, ethics, and a strategy capstone.',
